  --_gooey-action-success-fg: #4CAF50;
  --_gooey-action-success-bg-hover: #A5D6A7;
  --_gooey-action-success-bg-active: #81C784;
  --_gooey-action-error-bg: #FFCDD2;
  --_gooey-action-error-fg: #E53935;
  --_gooey-action-error-bg-hover: #EF9A9A;
  --_gooey-action-error-bg-active: #E57373;
  --_gooey-action-warning-bg: #FFECB3;
  --_gooey-action-warning-fg: #C49000;
  --_gooey-action-warning-bg-hover: #FFE082;
  --_gooey-action-warning-bg-active: #FFD54F;
  --_gooey-action-info-bg: #BBDEFB;
  --_gooey-action-info-fg: #1E88E5;
  --_gooey-action-info-bg-hover: #90CAF9;
  --_gooey-action-info-bg-active: #64B5F6;
  --_gooey-progress-track: rgba(0, 0, 0, 0.06);
  --_gooey-progress-default: #999;
  --_gooey-progress-success: #4CAF50;
  --_gooey-progress-error: #E53935;
  --_gooey-progress-warning: #C49000;
  --_gooey-progress-info: #1E88E5;
}

.gooey-wrapper[data-theme="dark"] {
  --_gooey-fill: #1a1a1a;
  --_gooey-title-default: #ccc;
  --_gooey-title-success: #66BB6A;
  --_gooey-title-error: #EF5350;
  --_gooey-title-warning: #FFB300;
  --_gooey-title-info: #42A5F5;
  --_gooey-title-loading: #ccc;
  --_gooey-timestamp: #777;
  --_gooey-description: #e0e0e0;
  --_gooey-close-fg: #e0e0e0;
  --_gooey-action-default-bg: #3a3a3a;
  --_gooey-action-default-fg: #ccc;
  --_gooey-action-default-bg-hover: #444;
  --_gooey-action-default-bg-active: #4e4e4e;
  --_gooey-action-success-bg: #1b5e20;
  --_gooey-action-success-fg: #66BB6A;
  --_gooey-action-success-bg-hover: #2e7d32;
  --_gooey-action-success-bg-active: #388e3c;
  --_gooey-action-error-bg: #b71c1c;
  --_gooey-action-error-fg: #EF5350;
  --_gooey-action-error-bg-hover: #c62828;
  --_gooey-action-error-bg-active: #d32f2f;
  --_gooey-action-warning-bg: #4a3800;
  --_gooey-action-warning-fg: #FFB300;
  --_gooey-action-warning-bg-hover: #5c4600;
  --_gooey-action-warning-bg-active: #6e5400;
  --_gooey-action-info-bg: #0d47a1;
  --_gooey-action-info-fg: #42A5F5;
  --_gooey-action-info-bg-hover: #1565c0;
  --_gooey-action-info-bg-active: #1976d2;
  --_gooey-progress-track: rgba(255, 255, 255, 0.1);
  --_gooey-progress-default: #888;
  --_gooey-progress-success: #66BB6A;
  --_gooey-progress-error: #EF5350;
  --_gooey-progress-warning: #FFB300;
  --_gooey-progress-info: #42A5F5;
}

/* ============================================
   Wrapper: single container for both states
   ============================================ */
.gooey-wrapper {
  pointer-events: auto;
  cursor: default;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
  position: relative;
  width: fit-content;
}

/* SVG background: parametric morph from pill to blob */
.gooey-blobSvg {
  position: absolute;
  top: 0;
  left: 0;
  overflow: visible;
  pointer-events: none;
  filter: drop-shadow(0 4px 12px rgba(0, 0, 0, 0.06))
          drop-shadow(0 1px 4px rgba(0, 0, 0, 0.04));
}

.gooey-blobPath {
  fill: var(--gooey-fill, var(--_gooey-fill));
  stroke: var(--gooey-border, transparent);
  stroke-width: var(--gooey-border-width, 1.5px);
}

/* Content on top of SVG background */
.gooey-content {
  position: relative;
  z-index: 1;
  transition: padding 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.gooey-contentCompact {
  padding: 7px 10px 7px 10px;
}

.gooey-contentExpanded {
  padding: 7px 10px 16px 10px;
  min-width: 300px;
  max-width: 380px;
}

/* ============================================
   Shared
   ============================================ */
.gooey-header {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: inherit;
}

.gooey-header > .gooey-title,
.gooey-header > .gooey-timestamp {
  min-width: 0;
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
}

.gooey-header > .gooey-timestamp {
  margin-left: auto;
}

.gooey-iconWrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  line-height: 0;
}

.gooey-title {
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
  color: inherit;
  padding: 0 4px 2px 2px;
}

.gooey-titleDefault { color: var(--gooey-title-default, var(--_gooey-title-default)); }
.gooey-titleSuccess { color: var(--gooey-title-success, var(--_gooey-title-success)); }
.gooey-titleError { color: var(--gooey-title-error, var(--_gooey-title-error)); }
.gooey-titleWarning { color: var(--gooey-title-warning, var(--_gooey-title-warning)); }
.gooey-titleInfo { color: var(--gooey-title-info, var(--_gooey-title-info)); }
.gooey-titleLoading { color: var(--gooey-title-loading, var(--_gooey-title-loading)); }

.gooey-timestamp {
  font-size: 11px;
  font-weight: 400;
  color: var(--gooey-timestamp, var(--_gooey-timestamp));
  white-space: nowrap;
  line-height: 1;
  padding-left: 6px;
}

.gooey-description {
  font-size: 13px;
  font-weight: 400;
  color: var(--gooey-description, var(--_gooey-description));
  line-height: 1.55;
  margin-top: 16px;
  overflow: hidden;
}

.gooey-actionWrapper {
  margin-top: 12px;
  overflow: hidden;
}

.gooey-actionButton {
  display: block;
  box-sizing: border-box;
  width: 100%;
  border: none;
  border-radius: 999px;
  padding: 10px 20px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  text-align: center;
  outline: none;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.15s ease;
}

.gooey-actionButton:focus:not(:focus-visible) {
  outline: none;
}

.gooey-actionButton:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.gooey-actionDefault {
  background: var(--gooey-action-default-bg, var(--_gooey-action-default-bg));
  color: var(--gooey-action-default-fg, var(--_gooey-action-default-fg));
}
.gooey-actionDefault:hover { background: var(--gooey-action-default-bg-hover, var(--gooey-action-default-bg, var(--_gooey-action-default-bg-hover))); }
.gooey-actionDefault:active { background: var(--gooey-action-default-bg-active, var(--gooey-action-default-bg, var(--_gooey-action-default-bg-active))); }

.gooey-actionSuccess {
  background: var(--gooey-action-success-bg, var(--_gooey-action-success-bg));
  color: var(--gooey-action-success-fg, var(--_gooey-action-success-fg));
}
.gooey-actionSuccess:hover { background: var(--gooey-action-success-bg-hover, var(--gooey-action-success-bg, var(--_gooey-action-success-bg-hover))); }
.gooey-actionSuccess:active { background: var(--gooey-action-success-bg-active, var(--gooey-action-success-bg, var(--_gooey-action-success-bg-active))); }

.gooey-actionError {
  background: var(--gooey-action-error-bg, var(--_gooey-action-error-bg));
  color: var(--gooey-action-error-fg, var(--_gooey-action-error-fg));
}
.gooey-actionError:hover { background: var(--gooey-action-error-bg-hover, var(--gooey-action-error-bg, var(--_gooey-action-error-bg-hover))); }
.gooey-actionError:active { background: var(--gooey-action-error-bg-active, var(--gooey-action-error-bg, var(--_gooey-action-error-bg-active))); }

.gooey-actionWarning {
  background: var(--gooey-action-warning-bg, var(--_gooey-action-warning-bg));
  color: var(--gooey-action-warning-fg, var(--_gooey-action-warning-fg));
}
.gooey-actionWarning:hover { background: var(--gooey-action-warning-bg-hover, var(--gooey-action-warning-bg, var(--_gooey-action-warning-bg-hover))); }
.gooey-actionWarning:active { background: var(--gooey-action-warning-bg-active, var(--gooey-action-warning-bg, var(--_gooey-action-warning-bg-active))); }

.gooey-actionInfo {
  background: var(--gooey-action-info-bg, var(--_gooey-action-info-bg));
  color: var(--gooey-action-info-fg, var(--_gooey-action-info-fg));
}
.gooey-actionInfo:hover { background: var(--gooey-action-info-bg-hover, var(--gooey-action-info-bg, var(--_gooey-action-info-bg-hover))); }
.gooey-actionInfo:active { background: var(--gooey-action-info-bg-active, var(--gooey-action-info-bg, var(--_gooey-action-info-bg-active))); }

/* ============================================
   Progress countdown bar
   ============================================ */
.gooey-progressWrapper {
  margin-top: 10px;
  overflow: hidden;
  border-radius: 2px;
  height: 3px;
  background: var(--gooey-progress-track, var(--_gooey-progress-track));
}

.gooey-progressBar {
  height: 100%;
  border-radius: 2px;
  transform-origin: left center;
  animation: gooey-progress-shrink var(--gooey-progress-duration, 4000ms) linear forwards;
  animation-play-state: running;
}

.gooey-progressPaused .gooey-progressBar {
  animation-play-state: paused;
}

@keyframes gooey-progress-shrink {
  from { transform: scaleX(1); }
  to { transform: scaleX(0); }
}

.gooey-progressDefault { background: var(--gooey-progress-default, var(--_gooey-progress-default)); }
.gooey-progressSuccess { background: var(--gooey-progress-success, var(--_gooey-progress-success)); }
.gooey-progressError { background: var(--gooey-progress-error, var(--_gooey-progress-error)); }
.gooey-progressWarning { background: var(--gooey-progress-warning, var(--_gooey-progress-warning)); }
.gooey-progressInfo { background: var(--gooey-progress-info, var(--_gooey-progress-info)); }

/* ============================================
   Dark mode (colors come from the theme variables above)
   ============================================ */

.gooey-wrapper[data-theme="dark"] .gooey-blobSvg {
  filter: drop-shadow(0 4px 12px rgba(0, 0, 0, 0.3))
          drop-shadow(0 1px 4px rgba(0, 0, 0, 0.2));
}

/* ---------------------------------------------------------------------------
   Close button: appears on hover, positioned top-left by default.
   Use closeButton="top-right" on GooeyToaster for top-right placement.
   Border and background follow the same --gooey-* vars as the toast body.
   --------------------------------------------------------------------------- */
.gooey-closeButton {
  position: absolute;
  top: -6px;
  left: -6px;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  box-sizing: border-box;
  border-style: solid;
  border-width: var(--gooey-border-width, 1.5px);
  border-color: var(--gooey-border, transparent);
  border-radius: 50%;
  background: var(--gooey-fill, var(--_gooey-fill));
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);
  color: var(--gooey-close-fg, var(--_gooey-close-fg));
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s ease, transform 0.15s ease;
  pointer-events: none;
  outline: none;
  -webkit-tap-highlight-color: transparent;
}
.gooey-closeButtonRight {
  left: auto;
  right: -1px;
  top: 6px;
}
.gooey-wrapper:hover .gooey-closeButton,
.gooey-wrapper:focus-within .gooey-closeButton,
.gooey-wrapper:active .gooey-closeButton {
  opacity: 1;
  pointer-events: auto;
}
.gooey-closeButton:focus,
.gooey-closeButton:focus-visible {
  opacity: 1;
  pointer-events: auto;
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.15);
}
.gooey-closeButton:hover {
  transform: scale(1.15);
}
.gooey-closeButton:active {
  transform: scale(0.95);
}

/* ============================================
   Forced colors (Windows High Contrast)
   ============================================ */
@media (forced-colors: active) {
  .gooey-blobPath {
    fill: Canvas;
    stroke: CanvasText;
    stroke-width: 1.5px;
  }
  .gooey-blobSvg { filter: none; }
  .gooey-title,
  .gooey-timestamp,
  .gooey-description { color: CanvasText; }
  .gooey-actionButton {
    background: ButtonFace;
    color: ButtonText;
    border: 1px solid ButtonText;
  }
  .gooey-actionButton:focus-visible { outline: 2px solid Highlight; }
  .gooey-progressWrapper { background: Canvas; border: 1px solid CanvasText; }
  .gooey-progressBar { background: Highlight; }
  .gooey-closeButton {
    background: Canvas;
    color: CanvasText;
    border: 1px solid CanvasText;
    box-shadow: none;
  }
}
